import{_ as t,o as i,c as o,a}from"./app.BAI08CEQ.js";const f=JSON.parse('{"title":"Constitutional Enforcement & Proof of Alignment (WP-3001)","description":"","frontmatter":{},"headers":[],"relativePath":"reference/CONSTITUTIONAL_ENFORCEMENT_DEPTH.md","filePath":"reference/CONSTITUTIONAL_ENFORCEMENT_DEPTH.md","lastUpdated":1771753292000}'),n={name:"reference/CONSTITUTIONAL_ENFORCEMENT_DEPTH.md"};function r(l,e,s,c,d,u){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="constitutional-enforcement-proof-of-alignment-wp-3001" tabindex="-1">Constitutional Enforcement &amp; Proof of Alignment (WP-3001) <a class="header-anchor" href="#constitutional-enforcement-proof-of-alignment-wp-3001" aria-label="Permalink to &quot;Constitutional Enforcement &amp; Proof of Alignment (WP-3001)&quot;">​</a></h1><p>This document defines how <code>thegent</code> enforces project-wide rules, ethics, and safety through <strong>Constitutional AI</strong> patterns.</p><h2 id="_1-the-project-constitution" tabindex="-1">1. The Project Constitution <a class="header-anchor" href="#_1-the-project-constitution" aria-label="Permalink to &quot;1. The Project Constitution&quot;">​</a></h2><p>The &quot;Constitution&quot; is a set of machine-readable principles (stored in <code>contracts/constitution.yaml</code>) that guide all agent activity. It extends the instructions found in <code>CLAUDE.md</code>.</p><h3 id="_1-1-core-principles-example" tabindex="-1">1.1 Core Principles (Example) <a class="header-anchor" href="#_1-1-core-principles-example" aria-label="Permalink to &quot;1.1 Core Principles (Example)&quot;">​</a></h3><ul><li><strong>Principle 1 (Safety)</strong>: Never perform irreversible destructive actions without simulation and human sign-off.</li><li><strong>Principle 2 (Privacy)</strong>: Never leak PII (Personally Identifiable Information) into logs or external provider prompts.</li><li><strong>Principle 3 (Efficiency)</strong>: Favor existing project patterns over new library dependencies.</li></ul><h2 id="_2-enforcement-via-policy-engine" tabindex="-1">2. Enforcement via Policy Engine <a class="header-anchor" href="#_2-enforcement-via-policy-engine" aria-label="Permalink to &quot;2. Enforcement via Policy Engine&quot;">​</a></h2><p>The <code>PolicyEngine</code> (OPA/Rego) acts as the <strong>Constitutional Guard</strong>:</p><h3 id="_2-1-pre-execution-critique" tabindex="-1">2.1 Pre-Execution Critique <a class="header-anchor" href="#_2-1-pre-execution-critique" aria-label="Permalink to &quot;2.1 Pre-Execution Critique&quot;">​</a></h3><p>Before an agent executes a high-risk tool call:</p><ol><li>The <code>Orchestrator</code> sends the proposed action to a specialized <strong>Critique Agent</strong>.</li><li>The Critique Agent evaluates the action against the Constitution.</li><li>If a violation is found, the Critique Agent generates a &quot;Constitutional Rebuke.&quot;</li><li>The acting agent must then &quot;Self-Correct&quot; the proposal before it is sent to the human for approval.</li></ol><h3 id="_2-2-proof-of-alignment-poa" tabindex="-1">2.2 Proof of Alignment (PoA) <a class="header-anchor" href="#_2-2-proof-of-alignment-poa" aria-label="Permalink to &quot;2.2 Proof of Alignment (PoA)&quot;">​</a></h3><p>Every <strong>MAIF artifact</strong> must include a <code>Proof_of_Alignment</code> metadata block:</p><ul><li><strong>Verified Principles</strong>: A list of constitutional principles checked during the run.</li><li><strong>Critique Hash</strong>: A cryptographic signature from the Critique Agent verifying alignment.</li></ul><h2 id="_3-constitutional-drift-detection" tabindex="-1">3. Constitutional Drift Detection <a class="header-anchor" href="#_3-constitutional-drift-detection" aria-label="Permalink to &quot;3. Constitutional Drift Detection&quot;">​</a></h2><p>The <strong>Gardener</strong> scans the <strong>Immutable Audit Trail</strong> for &quot;Constitutional Drift&quot;:</p><ul><li><strong>Pattern Matching</strong>: Identifying sequences of actions that, while individually policy-compliant, semantically violate a principle (e.g., &quot;Boilerplate Proliferation&quot;).</li><li><strong>Alerting</strong>: Drift &gt; Threshold triggers an automatic &quot;Constitutional Audit&quot; run.</li></ul><hr><p><em>Cross-ref: <a href="./ROBUSTNESS_AND_FUTURE_DEPTH.html">ROBUSTNESS_AND_FUTURE_DEPTH.md</a> | <a href="./MAIF_ARTIFACT_SPEC_DEPTH.html">MAIF_ARTIFACT_SPEC_DEPTH.md</a></em></p><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../reference/WORK_STREAM.html">WORK_STREAM.md</a> — canonical backlog</li><li><a href="./../plans/00-MASTER-INDEX.html">00-MASTER-INDEX.md</a> — plan index</li></ul><hr><h2 id="extension-summary" tabindex="-1">EXTENSION_SUMMARY <a class="header-anchor" href="#extension-summary" aria-label="Permalink to &quot;EXTENSION_SUMMARY&quot;">​</a></h2><p><strong>Extended on:</strong> 2026-02-17 <strong>Extended by:</strong> Claude Code</p><h3 id="changes-made" tabindex="-1">Changes Made <a class="header-anchor" href="#changes-made" aria-label="Permalink to &quot;Changes Made&quot;">​</a></h3><ol><li>Added practical implementation patterns</li><li>Added configuration examples</li><li>Enhanced cross-references to related documentation</li></ol><h3 id="cross-references-added" tabindex="-1">Cross-References Added <a class="header-anchor" href="#cross-references-added" aria-label="Permalink to &quot;Cross-References Added&quot;">​</a></h3><ul><li>Related research and implementation guides</li><li>WORK_STREAM.md for tracking</li></ul><h3 id="practical-additions" tabindex="-1">Practical Additions <a class="header-anchor" href="#practical-additions" aria-label="Permalink to &quot;Practical Additions&quot;">​</a></h3><ul><li>Implementation templates</li><li>Configuration examples</li><li>Best practices</li></ul>',31)])])}const p=t(n,[["render",r]]);export{f as __pageData,p as default};
